   ],
   "ports": [
    "PaymentOrderRepository",
    "CompanyTariffRepository",
    "ServiceCatalogRepository",
    "AccountRepository",
    "DebitGateway"
   ],
   "http_method": "POST",
   "path": "/payment-orders/payments",
   "legacy_program": "dbo.sp_pago_orden",
   "unit_of_work": {
    "begins_at": 108,
    "commits_at": 161,
    "savepoints": [],
    "rollbacks": [
     {
      "legacy_line": 119,
      "outcome": "DEBIT_FAILED"
     },
     {
      "legacy_line": 136,
      "outcome": "COMMISSION_FAILED"
     },
     {
      "legacy_line": 155,
      "outcome": "ORDER_UPDATE_FAILED"
     }
    ]
   },
   "legacy_message": "@o_mensaje"
  }
 ],
 "decisions": [
  {
   "title": "Transaction boundary owned by the REST adapter",
   "context": "The legacy opens the transaction at line 108 (after all validations and calculations) and rolls back at lines 119, 136 and 155 before returning a non-zero status.",
   "decision": "The program rejects with a non-zero status, so the REST adapter owns the transaction. Any business error undoes all the work, and no UnitOfWork port is declared because there are no savepoints.",
   "consequences": "The service starts the transaction before the debit, as the legacy does, and a rejection (DEBIT_FAILED, COMMISSION_FAILED, ORDER_UPDATE_FAILED) rolls it back. The target keeps the legacy validation order."
  },
  {
   "title": "Debit program as a gateway port",
   "context": "db_cuentas..sp_debito is an external program that returns a status and the movement sequence.",
   "decision": "It is exposed as DebitGateway. The status is read with the reserved name 'return' and the movement through @o_secuencial. A non-zero status is the DEBIT_FAILED or COMMISSION_FAILED rejection. The legacy '@@error <> 0' check is replaced by exceptions.",
   "consequences": "If the debit executes outside the target database transaction, undoing an already executed first debit after a later failure needs the gateway to take part in the same transaction or a compensation. This must be confirmed when the adapter is built."
  },
  {
   "title": "Data moves to the target database",
   "context": "data_strategy is migration: the legacy tables db_pagos..pg_orden, db_admin..ad_tarifa_empresa, db_admin..ad_servicio and db_cuentas..ct_cuenta move to PostgreSQL with snake_case names.",
   "decision": "One entity per table and one repository port per entity. Legacy precision is kept (money as decimal(19,4)). DebitResult is a result-only entity of the gateway and has no table.",
   "consequences": "The balance read and the order update run against the target database. The debit still goes through the external program."
  },
  {
   "title": "Null semantics preserved",
   "context": "In the legacy, a missing account leaves @w_saldo null, and null comparisons are false. A null tariff becomes 0, and a null separate flag falls into the 'add commission' branch.",
   "decision": "A missing account does not raise INSUFFICIENT_FUNDS; the flow continues to the debit, which fails with DEBIT_FAILED. A null tariff (company or service, or service missing) is 0. A flag different from 'S' (including null) adds the commission to the total.",
   "consequences": "Behaviour is equivalent to the legacy even in these edge cases."
  },
  {
   "title": "Commission rounding and channel default",
   "context": "The WEB commission is round(tariff/2, 2) in Sybase money arithmetic. The channel defaults to 'WEB' when not supplied.",
   "decision": "Use BigDecimal with scale 2 and HALF_UP (away from zero) rounding, and store it with 4 decimals. A missing channel in the request is treated as 'WEB'. NOMINA always gets commission 0.",
   "consequences": "Same results as the legacy for positive tariffs; the golden master covers the rounding cases."
  },
  {
   "title": "Error plumbing not translated",
   "context": "The legacy ERROR label calls cobis..sp_cerror and returns @w_error.",
   "decision": "Error logging is infrastructure and is replaced by business exceptions carrying the stable code and the legacy message.",
   "consequences": "The REST adapter maps each error to the legacy code and message (@o_mensaje); success returns 'PAGO REALIZADO' and the movement."
  }
 ],
 "masks": [],
 "infrastructure": [
  "cobis..sp_cerror"
 ],
 "data_strategy": "migration"
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Account type must be CTE, AHO or VIR",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment order is only accepted for account types CTE, AHO or VIR. Any other account type is rejected with error 50001 and the message 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "@i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')",
  "action": "Set @w_error = 50001 and @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'.",
  "inputs": [
   {
    "name": "@i_tipo_cuenta",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type is allowed\n  Given the account type is 'AHO'\n  When the payment order is validated\n  Then no error is set for the account type",
   "Scenario: Account type is not allowed\n  Given the account type is 'PRE'\n  When the payment order is validated\n  Then the error code is 50001\n  And the message is 'TIPO DE CUENTA NO PERMITIDO'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 34,
    "line_end": 37
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Payment order must be pending to be paid",
  "category": "validation",
  "priority": "P0",
  "statement": "An order can only proceed when its status is 'P' (pending). Any other status is rejected with error 50003 and the message 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "The status ord_estado of the order identified by @i_orden and @i_empresa in db_pagos..pg_orden is not 'P'.",
  "action": "Set @w_error = 50003 and @o_mensaje = 'ORDEN NO ESTA PENDIENTE'. The slice does not show what happens after the error is set.",
  "inputs": [
   {
    "name": "@i_orden",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "ord_estado",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order is pending\n  Given order 100 of company 1 has status 'P'\n  When the payment procedure checks the order\n  Then no error is raised by this check",
   "Scenario: Order is not pending\n  Given order 100 of company 1 has status 'X'\n  When the payment procedure checks the order\n  Then @w_error is 50003\n  And @o_mensaje is 'ORDEN NO ESTA PENDIENTE'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 42,
    "line_end": 45
   },
   {
    "file": "sp/sp_pago_orden.sp",
