        PayOrderService service() {
            PaymentOrderRepository orders = new PaymentOrderRepository() {
                @Override
                public Optional<PaymentOrder> findByNumberAndCompany(Integer orderNumber, Integer companyId) {
                    calls.add("findOrder");
                    orderLookups.add(orderNumber + "/" + companyId);
                    return order;
                }

                @Override
                public int markPaid(Integer orderNumber, Integer companyId, LocalDateTime paymentDate,
                                    BigDecimal commission) {
                    calls.add("markPaid");
                    paid.add(new PaidCall(orderNumber, companyId, paymentDate, commission));
                    return markPaidRows;
                }
            };
            CompanyTariffRepository tariffs = (companyId, serviceCode) -> {
                calls.add("findCompanyTariff");
                return companyTariff;
            };
            ServiceCatalogRepository services = serviceCode -> {
                calls.add("findService");
                return service;
            };
            AccountRepository accounts = (number, type) -> {
                calls.add("findAccount");
                return account;
            };
            DebitGateway gateway = new DebitGateway() {
                @Override
                public Optional<DebitResult> debit(String accountNumber, String accountType, BigDecimal amount,
                                                   String reference) {
                    calls.add("debit");
                    debits.add(new DebitCall(accountNumber, accountType, amount, reference));
                    return debitResult;
                }

                @Override
                public int debitCommission(String accountNumber, String accountType, BigDecimal amount,
                                           String reference) {
                    calls.add("debitCommission");
                    commissionDebits.add(new DebitCall(accountNumber, accountType, amount, reference));
                    return commissionReturn;
                }
            };
            return new PayOrderService(orders, tariffs, services, accounts, gateway);
        }

        PayOrderResponse run(PayOrderRequest request) {
            return service().execute(request);
        }

        void assertRejected(PayOrderRequest request, String code, String legacyCode, String message) {
            assertThatThrownBy(() -> service().execute(request))
                    .isInstanceOfSatisfying(BusinessError.class, e -> {
                        assertThat(e.code()).isEqualTo(code);
                        assertThat(e.legacyCode()).isEqualTo(legacyCode);
                        assertThat(e.getMessage()).isEqualTo(message);
                    });
        }
    }

    private static PayOrderRequest request(String accountType, String serviceCode, String channel, String amount) {
        return new PayOrderRequest(100, 1, serviceCode, accountType, "1234567890",
                new BigDecimal(amount), channel, PROCESS_DATE);
    }

    private static PayOrderRequest defaultRequest() {
        return request("AHO", "LUZ", "VEN", "100.00");
    }

    private static Account account(String type, String balance) {
        return new Account("1234567890", type, balance == null ? null : new BigDecimal(balance));
    }

