package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.CompanyTariff;
import com.bank.payments.domain.model.DebitResult;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.model.ServiceCatalog;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.CompanyTariffRepository;
import com.bank.payments.domain.port.DebitGateway;
import com.bank.payments.domain.port.PaymentOrderRepository;
import com.bank.payments.domain.port.ServiceCatalogRepository;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

/** Application service of PayOrder (legacy dbo.sp_pago_orden). */
public class PayOrderService {

    private static final BigDecimal TWO = new BigDecimal("2");
    private static final BigDecimal OVERDRAFT_MARGIN = new BigDecimal("100.00");

    private final PaymentOrderRepository paymentOrderRepository;
    private final CompanyTariffRepository companyTariffRepository;
    private final ServiceCatalogRepository serviceCatalogRepository;
    private final AccountRepository accountRepository;
    private final DebitGateway debitGateway;

    public PayOrderService(PaymentOrderRepository paymentOrderRepository,
                           CompanyTariffRepository companyTariffRepository,
                           ServiceCatalogRepository serviceCatalogRepository,
                           AccountRepository accountRepository,
                           DebitGateway debitGateway) {
        this.paymentOrderRepository = paymentOrderRepository;
        this.companyTariffRepository = companyTariffRepository;
        this.serviceCatalogRepository = serviceCatalogRepository;
        this.accountRepository = accountRepository;
        this.debitGateway = debitGateway;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        // Parameter default: @i_canal = 'WEB' when not supplied
        String channel = request.channel() == null ? "WEB" : request.channel();

        // RULE-001: null in "not in (...)" is UNKNOWN, so it does not reject
        String accountType = request.accountType();
        if (accountType != null
                && !(sameChar(accountType, "CTE") || sameChar(accountType, "AHO") || sameChar(accountType, "VIR"))) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003 / RULE-002
        Optional<PaymentOrder> order =
                paymentOrderRepository.findByNumberAndCompany(request.orderNumber(), request.companyId());
        if (order.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }
        String status = order.get().status();
        // null <> 'P' is UNKNOWN: not rejected
        if (status != null && !sameChar(status, "P")) {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004: tariff and separate-charge flag
        BigDecimal tariff = null;
        String separate = null;
        Optional<CompanyTariff> companyTariff =
                companyTariffRepository.findByCompanyAndService(request.companyId(), request.serviceCode());
        if (companyTariff.isPresent()) {
            tariff = companyTariff.get().tariffValue();
            separate = companyTariff.get().separateCharge();
        } else {
            Optional<ServiceCatalog> service = serviceCatalogRepository.findByCode(request.serviceCode());
            if (service.isPresent()) {
                tariff = service.get().defaultTariff();
                separate = "N";
            }
            // no row: variables keep their previous values (null)
        }
        if (tariff == null) {
            tariff = BigDecimal.ZERO;
        }

        // RULE-005: commission
        BigDecimal commission;
        if (sameChar(channel, "WEB")) {
            commission = tariff.divide(TWO).setScale(2, RoundingMode.HALF_UP);
        } else {
            commission = tariff;
        }
        if (sameChar(request.serviceCode(), "NOMINA")) {
            commission = BigDecimal.ZERO;
        }

        // RULE-006: total
        BigDecimal total;
        if (sameChar(separate, "S")) {
            total = request.amount();
        } else {
            total = request.amount() == null ? null : request.amount().add(commission);
        }

        // RULE-007: funds
        Optional<Account> account =
                accountRepository.findByNumberAndType(request.accountNumber(), request.accountType());
        BigDecimal balance = account.map(Account::balance).orElse(null);
        boolean insufficient = false;
        if (balance != null && total != null && accountType != null) {
            if (sameChar(accountType, "VIR")) {
                insufficient = balance.compareTo(total) < 0;
            } else {
                insufficient = balance.add(OVERDRAFT_MARGIN).compareTo(total) < 0;
            }
        }
        if (insufficient) {
            throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
        }

        // RULE-008: debit (the transaction boundary is generated around execute)
        Optional<DebitResult> debit = debitGateway.debit(
                request.accountNumber(), request.accountType(), total, "PAGO ORDEN");
        if (debit.isEmpty() || debit.get().returnCode() == null || debit.get().returnCode() != 0) {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }
        Integer movement = debit.get().movement();

        // RULE-009 / RULE-010: separate commission
        if (sameChar(separate, "S") && commission.compareTo(BigDecimal.ZERO) > 0) {
            int commissionReturn = debitGateway.debitCommission(
                    request.accountNumber(), request.accountType(), commission, "COMISION PAGO");
            if (commissionReturn != 0) {
                throw new BusinessError("COMMISSION_FAILED", "50006", "ERROR EN COMISION");
            }
        }

        // RULE-011 / RULE-012: mark the order paid
        int rows = paymentOrderRepository.markPaid(
                request.orderNumber(), request.companyId(), request.processDate(), commission);
        if (rows == 0) {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        // RULE-013
        return new PayOrderResponse(movement, "PAGO REALIZADO");
    }

    /** CHAR comparison: trailing spaces are ignored; null never equals anything. */
    private static boolean sameChar(String value, String literal) {
        return value != null && rtrim(value).equals(rtrim(literal));
    }

    private static String rtrim(String s) {
        int end = s.length();
        while (end > 0 && s.charAt(end - 1) == ' ') {
            end--;
        }
        return s.substring(0, end);
    }
}
